import { cells as g0 } from "./g0/index.mjs";
import { cells as g1 } from "./g1/index.mjs";
import { cells as g2 } from "./g2/index.mjs";
import { cells as g3 } from "./g3/index.mjs";
import { cells as g4 } from "./g4/index.mjs";
import { cells as g5 } from "./g5/index.mjs";
import { cells as g6 } from "./g6/index.mjs";
import { cells as g7 } from "./g7/index.mjs";

const all = [...g0, ...g1, ...g2, ...g3, ...g4, ...g5, ...g6, ...g7];

export function total(seed) {
  let sum = 0;
  for (const cell of all) sum += cell.apply(seed);
  return sum;
}

export function cells() {
  return all.length;
}

export function describe(value) {
  return `grid of ${all.length} cells: ${value}`;
}
